DELETE FROM notifications WHERE activity_id IN (SELECT id FROM activity_log WHERE video_id IN (SELECT v.id FROM videos v JOIN (VALUES ('V020','Nábor začíná u šéfa'),('V021','Hypotéka bez překvapení'),('V026','Dva šéfové, jeden problém'),('V031','Klient s chybou: fixace hypotéky'),('V032','Pět Radků'),('V028','Den za 15 sekund'),('V033','Hot take: volná pracovní doba'),('V036','Radek vs. Honza: kdo dřív')) AS d(code, title) ON d.code = v.code AND d.title = v.title));
